const cfg = $input.first().json;

// Absolute UTC boundaries, deliberately hardcoded so the instance clock cannot shift the window.
// Wed 2026-09-23 00:00:00Z .. Thu 2026-09-24 00:00:00Z (exclusive)
const START_UNIX = 1790121600;
const END_UNIX = 1790208000;

return [{ json: {
  zendesk_domain: cfg.zendesk_domain,
  automation_agent_id: cfg.automation_agent_id == null ? null : String(cfg.automation_agent_id),
  start_unix: START_UNIX,
  end_unix: END_UNIX,
  start_iso: new Date(START_UNIX * 1000).toISOString(),
  end_iso: new Date(END_UNIX * 1000).toISOString(),
  instance_clock_now: new Date().toISOString()
} }];

const w = $('Build window').first().json;
const agent = w.automation_agent_id;

const TAG_TIER = {
  'high-risk-legal-financial': 'A',
  'high-risk-conduct': 'B',
  'high-risk-safety-critical': 'C'
};

const byId = new Map();
for (const item of $input.all()) {
  const arr = (item.json && Array.isArray(item.json.tickets)) ? item.json.tickets : [];
  for (const t of arr) byId.set(String(t.id), t);
}
const all = Array.from(byId.values());

const startMs = w.start_unix * 1000;
const endMs = w.end_unix * 1000;

let maxCreated = null;
for (const t of all) {
  if (maxCreated === null || t.created_at > maxCreated) maxCreated = t.created_at;
}

const inWindow = all.filter(t => {
  const c = Date.parse(t.created_at);
  return c >= startMs && c < endMs;
});

function hrTags(t) {
  const tags = Array.isArray(t.tags) ? t.tags : [];
  return tags.filter(tag => TAG_TIER[tag]);
}

function isSolved(t) { return t.status === 'solved' || t.status === 'closed'; }

function bucket(t) {
  if (!isSolved(t)) return 'not_yet_solved';
  const a = t.assignee_id == null ? null : String(t.assignee_id);
  if (agent && a === agent) return 'automated';
  if (a) return 'manual';
  return 'solved_unassigned';
}

function tally(list, fn) {
  const m = {};
  for (const x of list) {
    const k = fn(x);
    if (k === null || k === undefined) continue;
    m[k] = (m[k] || 0) + 1;
  }
  return m;
}

function pct(n, d) { return d ? Math.round((n / d) * 1000) / 10 : 0; }

function stats(list) {
  const flagged = list.filter(t => hrTags(t).length > 0);
  const buckets = tally(list, bucket);
  const automated = buckets.automated || 0;
  const manual = buckets.manual || 0;
  const solvedUnassigned = buckets.solved_unassigned || 0;
  const notSolved = buckets.not_yet_solved || 0;
  const solved = automated + manual + solvedUnassigned;

  const perTier = { A: 0, B: 0, C: 0 };
  for (const t of flagged) {
    for (const tag of hrTags(t)) perTier[TAG_TIER[tag]]++;
  }

  const nonFlagged = list.filter(t => hrTags(t).length === 0);
  const nfBuckets = tally(nonFlagged, bucket);
  const nfAutomated = nfBuckets.automated || 0;
  const nfManual = nfBuckets.manual || 0;
  const nfSolved = nfAutomated + nfManual + (nfBuckets.solved_unassigned || 0);

  return {
    received: list.length,
    high_risk: {
      flagged: flagged.length,
      pct_of_received: pct(flagged.length, list.length),
      tier_A_legal_financial: perTier.A,
      tier_B_conduct: perTier.B,
      tier_C_safety_critical: perTier.C
    },
    automation: {
      solved: solved,
      pct_solved_of_received: pct(solved, list.length),
      automated: automated,
      manual: manual,
      solved_unassigned: solvedUnassigned,
      not_yet_solved: notSolved,
      automated_pct_of_solved: pct(automated, solved),
      automated_pct_of_received: pct(automated, list.length)
    },
    excluding_high_risk: {
      solved: nfSolved,
      automated: nfAutomated,
      manual: nfManual,
      automated_pct_of_solved: pct(nfAutomated, nfSolved)
    },
    status_breakdown: tally(list, t => t.status),
    high_risk_by_bucket: tally(flagged, bucket),
    non_high_risk_by_bucket: nfBuckets
  };
}

// Group by UTC calendar day, derived from the window rather than hardcoded
const days = {};
for (const t of inWindow) {
  const d = String(t.created_at).slice(0, 10);
  if (!days[d]) days[d] = [];
  days[d].push(t);
}
const byDay = {};
for (const d of Object.keys(days).sort()) byDay[d] = stats(days[d]);

return [{ json: {
  meta: {
    project_key: 'personality_prod',
    zendesk_domain: w.zendesk_domain,
    automation_agent_id: agent,
    window_start_utc: w.start_iso,
    window_end_utc: w.end_iso,
    definition: 'Automated = ticket is solved/closed AND the current assignee is the automation account (John). Manual = solved with a different assignee. Not-yet-solved tickets are reported separately and excluded from the automated/manual split.',
    tickets_pulled_total: all.length,
    latest_created_at_seen: maxCreated,
    instance_clock_now: w.instance_clock_now
  },
  by_day: byDay,
  total: stats(inWindow)
} }];
